UPDATE forge_io_task
SET status='WAITING',heartbeat_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP,updated_by=#{actor}
WHERE NOT deleted AND id=#{id} AND type='IMPORT' AND membership_id=#{member}
AND status='AWAITING_CONFIRM' AND heartbeat_at > #{cutoff}

